nextflow_process {

    name "Test Process PEDDY"
    script "modules/nf-core/peddy/main.nf"
    process "PEDDY"

    tag "modules"
    tag "modules_nfcore"
    tag "peddy"

    test("test - peddy") {

        config "./nextflow.plot.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz.tbi', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'ped_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM.ped', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'sites_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/peddy.sites', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                // .png bytes from matplotlib/peddy are not reproducible across
                // environments (font rendering, etc.) -- snapshot by filename
                // only, same pattern as modules/nf-core/nanoplot.
                { assert snapshot(
                    process.out.vs_html,
                    process.out.html,
                    process.out.ped,
                    file(process.out.het_check_png[0][1]).name,
                    file(process.out.ped_check_png[0][1]).name,
                    file(process.out.sex_check_png[0][1]).name,
                    process.out.het_check_csv,
                    process.out.ped_check_csv,
                    process.out.sex_check_csv,
                    process.out.ped_check_rel_difference_csv,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match() }

            )
        }

    }

    test("test - peddy - no_plot") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz.tbi', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'ped_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM.ped', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'sites_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/peddy.sites', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }

            )
        }

    }

    test("test - peddy - double_sites") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz.tbi', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'ped_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM.ped', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'sites_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/peddy.sites', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert !process.success },
                { assert process.exitStatus != 0 }
            )
        }
    }

    test("test - peddy - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM_snvs_annotated_ranked.vcf.gz.tbi', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'ped_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/FAM.ped', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'sites_file' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/peddy.sites', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }
}

